using Marketplace.Domain.Common; namespace Marketplace.Domain.Orders; public sealed class OrderItem:Entity<long>{private OrderItem(){} public long OrderId{get;private set;} public long ProductId{get;private set;} public long ProductVariantId{get;private set;} public string ProductNameSnapshot{get;private set;}=null!; public string VariantKeySnapshot{get;private set;}=null!; public string? SkuSnapshot{get;private set;} public long UnitPriceIRR{get;private set;} public int Quantity{get;private set;} public long LineSubtotalIRR{get;private set;} public long CampaignDiscountIRR{get;private set;} public long DirectDiscountIRR{get;private set;} public long CouponDiscountIRR{get;private set;} public long? WarrantyId{get;private set;} public string? WarrantyNameSnapshot{get;private set;} public long WarrantyAmountIRR{get;private set;} public long AllocatedShippingIRR{get;private set;} public long FinalLineTotalIRR{get;private set;} public long? CampaignId{get;private set;} public string? CampaignNameSnapshot{get;private set;} public static OrderItem Create(long id,long orderId,long productId,long variantId,string name,string variant,string? sku,long unit,int qty,long subtotal,long campaign,long direct,long coupon,long? warrantyId,string? warrantyName,long warranty,long shipping,long finalTotal,long? campaignId,string? campaignName){if(qty<=0||unit<0||subtotal<0||campaign<0||direct<0||coupon<0||warranty<0||shipping<0||finalTotal<0)throw new DomainException("Invalid order item.");return new(){Id=id,OrderId=orderId,ProductId=productId,ProductVariantId=variantId,ProductNameSnapshot=name,VariantKeySnapshot=variant,SkuSnapshot=sku,UnitPriceIRR=unit,Quantity=qty,LineSubtotalIRR=subtotal,CampaignDiscountIRR=campaign,DirectDiscountIRR=direct,CouponDiscountIRR=coupon,WarrantyId=warrantyId,WarrantyNameSnapshot=warrantyName,WarrantyAmountIRR=warranty,AllocatedShippingIRR=shipping,FinalLineTotalIRR=finalTotal,CampaignId=campaignId,CampaignNameSnapshot=campaignName};}}
